import { LitElement, html, css } from 'lit';
import { SignalWatcher, signal } from '@lit-labs/signals';

/**
 * <eeg-viewer> — Lit web component for interactive EEG visualization.
 *
 * Accepts an interactive SVG string (generated by stackplot_svg(..., interactive=True))
 * and provides:
 *   - Horizontal scale (seconds/page) control
 *   - Two-tier vertical gain: per-group and per-channel overrides
 *
 * Usage:
 *   <eeg-viewer svg-content="..."></eeg-viewer>
 *
 * Or set via JS:
 *   const viewer = document.querySelector('eeg-viewer');
 *   viewer.svgContent = svgString;
 */
class EegViewer extends SignalWatcher(LitElement) {
  static styles = css`
    :host {
      display: block;
      font-family: sans-serif;
    }
    .controls {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 4px 8px;
      background: #f5f5f5;
      border-bottom: 1px solid #ddd;
      font-size: 14px;
      flex-wrap: wrap;
    }
    .controls button {
      padding: 4px 12px;
      border: 1px solid #ccc;
      border-radius: 4px;
      background: white;
      cursor: pointer;
      font-size: 14px;
    }
    .controls button:hover {
      background: #e8e8e8;
    }
    .controls button.active {
      background: #4a90d9;
      color: white;
      border-color: #357abd;
    }
    .controls .scale-display {
      min-width: 80px;
      text-align: center;
      font-variant-numeric: tabular-nums;
    }
    .controls .separator {
      margin-left: 12px;
      border-left: 1px solid #ccc;
      padding-left: 12px;
    }
    .group-tabs {
      display: flex;
      gap: 4px;
    }
    .gain-target {
      font-weight: bold;
      min-width: 60px;
      text-align: center;
    }
    .svg-container {
      overflow: hidden;
    }
    .svg-container svg {
      display: block;
      width: 100%;
      height: auto;
    }
  `;

  // Horizontal scale
  #secondsPerPage = signal(10);

  // Two-tier gain model
  #groupGains = signal({});       // { "EEG": 1.0, "EKG": 0.5, ... }
  #channelGains = signal({});     // sparse per-channel overrides: { "3": 1.5 }
  #activeGroup = signal(null);    // currently selected group name
  #selectedChannel = signal(null); // null = group mode, index = individual mode

  // Internal: group names list and channel-to-group mapping
  #groupNames = [];
  #channelToGroup = {};

  static properties = {
    svgContent: { type: String, attribute: 'svg-content' },
  };

  constructor() {
    super();
    this.svgContent = '';
  }

  render() {
    const spp = this.#secondsPerPage.get();
    const groupGains = this.#groupGains.get();
    const channelGains = this.#channelGains.get();
    const activeGroup = this.#activeGroup.get();
    const selectedChannel = this.#selectedChannel.get();

    // Determine what the gain display shows
    let gainLabel;
    let gainValue;
    if (selectedChannel !== null) {
      const chLabel = this.#getChannelLabel(selectedChannel);
      gainValue = (channelGains[selectedChannel] ?? 1.0);
      gainLabel = chLabel;
    } else if (activeGroup !== null) {
      gainValue = (groupGains[activeGroup] ?? 1.0);
      gainLabel = activeGroup;
    } else {
      gainValue = 1.0;
      gainLabel = 'all';
    }

    return html`
      <div class="controls">
        <button @click=${this.#zoomIn} title="Show fewer seconds (zoom in)">+</button>
        <button @click=${this.#zoomOut} title="Show more seconds (zoom out)">&minus;</button>
        <span class="scale-display">${spp}s/page</span>

        <span class="separator">
          <button @click=${this.#gainUp} title="Increase gain">&uarr;</button>
          <button @click=${this.#gainDown} title="Decrease gain">&darr;</button>
          <span class="gain-target">${gainLabel}</span>
          <span class="scale-display">${gainValue.toFixed(1)}x</span>
        </span>

        ${this.#groupNames.length > 1 ? html`
          <span class="separator group-tabs">
            ${this.#groupNames.map(name => html`
              <button
                class=${activeGroup === name && selectedChannel === null ? 'active' : ''}
                @click=${() => this.#selectGroup(name)}
              >${name}</button>
            `)}
          </span>
        ` : ''}
      </div>
      <div class="svg-container"></div>
    `;
  }

  updated(changedProperties) {
    if (changedProperties.has('svgContent') && this.svgContent) {
      const container = this.shadowRoot.querySelector('.svg-container');
      container.innerHTML = this.svgContent;

      const svg = container.querySelector('svg[data-interactive]');
      if (svg) {
        // Read initial seconds
        const initialSeconds = parseFloat(svg.dataset.seconds);
        if (initialSeconds && !isNaN(initialSeconds)) {
          this.#secondsPerPage.set(initialSeconds);
        }

        // Parse channel groups from SVG
        this.#initChannelGroups(svg);

        // Set up click handlers on channel labels for individual selection
        this.#initLabelClickHandlers(svg);
      }
    }
    this.#applyScale();
  }

  #initChannelGroups(svg) {
    // Read group names from SVG root attribute, or discover from channels
    const groupsAttr = svg.dataset.channelGroups;
    if (groupsAttr) {
      this.#groupNames = JSON.parse(groupsAttr);
    } else {
      // Discover from data-channel-group attributes on channel elements
      const groups = new Set();
      svg.querySelectorAll('g.channel').forEach(ch => {
        groups.add(ch.dataset.channelGroup || 'default');
      });
      this.#groupNames = groups.size > 0 ? [...groups] : ['default'];
    }

    // Build channel-to-group mapping
    this.#channelToGroup = {};
    svg.querySelectorAll('g.channel').forEach(ch => {
      const idx = ch.dataset.channelIndex;
      this.#channelToGroup[idx] = ch.dataset.channelGroup || 'default';
    });

    // Initialize group gains (all 1.0)
    const gains = {};
    for (const name of this.#groupNames) {
      gains[name] = 1.0;
    }
    this.#groupGains.set(gains);
    this.#channelGains.set({});
    this.#activeGroup.set(this.#groupNames[0] || null);
    this.#selectedChannel.set(null);
  }

  #initLabelClickHandlers(svg) {
    // Find the channel-labels group and make labels clickable
    const labelsG = svg.querySelector('g.channel-labels');
    if (!labelsG) return;

    const labels = labelsG.querySelectorAll('text');
    // Labels are drawn in channel_order (draw_idx), so index in the list = draw_idx
    labels.forEach((labelEl, drawIdx) => {
      labelEl.style.cursor = 'pointer';
      labelEl.addEventListener('click', () => {
        const current = this.#selectedChannel.get();
        if (current === drawIdx) {
          // Click again → deselect, back to group mode
          this.#selectedChannel.set(null);
          labelEl.style.fontWeight = '';
        } else {
          // Deselect previous
          if (current !== null) {
            const prevLabel = labels[current];
            if (prevLabel) prevLabel.style.fontWeight = '';
          }
          this.#selectedChannel.set(drawIdx);
          labelEl.style.fontWeight = 'bold';
        }
        this.requestUpdate();
      });
    });
  }

  #getChannelLabel(drawIdx) {
    const svg = this.shadowRoot.querySelector('svg[data-interactive]');
    if (!svg) return `ch${drawIdx}`;
    const ch = svg.querySelector(`g.channel[data-channel-index="${drawIdx}"]`);
    return ch ? (ch.dataset.label || `ch${drawIdx}`) : `ch${drawIdx}`;
  }

  #selectGroup(name) {
    // Deselect any individual channel
    if (this.#selectedChannel.get() !== null) {
      this.#deselectChannel();
    }
    this.#activeGroup.set(name);
    this.requestUpdate();
  }

  #deselectChannel() {
    const svg = this.shadowRoot.querySelector('svg[data-interactive]');
    if (svg) {
      const labelsG = svg.querySelector('g.channel-labels');
      if (labelsG) {
        labelsG.querySelectorAll('text').forEach(el => {
          el.style.fontWeight = '';
        });
      }
    }
    this.#selectedChannel.set(null);
  }

  #zoomIn = () => {
    const current = this.#secondsPerPage.get();
    if (current > 1) {
      this.#secondsPerPage.set(Math.max(1, Math.round(current / 2)));
    }
  };

  #zoomOut = () => {
    const current = this.#secondsPerPage.get();
    const svg = this.shadowRoot.querySelector('svg[data-interactive]');
    const maxSeconds = svg ? parseFloat(svg.dataset.seconds) : 300;
    this.#secondsPerPage.set(Math.min(maxSeconds, current * 2));
  };

  #gainUp = () => {
    const selected = this.#selectedChannel.get();
    if (selected !== null) {
      const gains = { ...this.#channelGains.get() };
      gains[selected] = (gains[selected] ?? 1.0) * 1.5;
      this.#channelGains.set(gains);
    } else {
      const group = this.#activeGroup.get();
      if (group !== null) {
        const gains = { ...this.#groupGains.get() };
        gains[group] = (gains[group] ?? 1.0) * 1.5;
        this.#groupGains.set(gains);
      }
    }
  };

  #gainDown = () => {
    const selected = this.#selectedChannel.get();
    if (selected !== null) {
      const gains = { ...this.#channelGains.get() };
      gains[selected] = Math.max(0.1, (gains[selected] ?? 1.0) / 1.5);
      this.#channelGains.set(gains);
    } else {
      const group = this.#activeGroup.get();
      if (group !== null) {
        const gains = { ...this.#groupGains.get() };
        gains[group] = Math.max(0.1, (gains[group] ?? 1.0) / 1.5);
        this.#groupGains.set(gains);
      }
    }
  };

  #applyScale() {
    const newSeconds = this.#secondsPerPage.get();
    const groupGains = this.#groupGains.get();
    const channelGains = this.#channelGains.get();
    const svg = this.shadowRoot.querySelector('svg[data-interactive]');
    if (!svg) return;

    const plotWidth = parseFloat(svg.dataset.plotWidth);
    const labelMargin = parseFloat(svg.dataset.labelMargin);
    const newPxPerSec = plotWidth / newSeconds;

    // Update channel transforms with two-tier gain
    svg.querySelectorAll('g.channel').forEach(ch => {
      const baselineY = parseFloat(ch.dataset.baselineY);
      const yScale = parseFloat(ch.dataset.yScale);
      const chIdx = ch.dataset.channelIndex;
      const chGroup = ch.dataset.channelGroup || 'default';

      const groupGain = groupGains[chGroup] ?? 1.0;
      const channelGain = channelGains[chIdx] ?? 1.0;
      const effectiveGain = groupGain * channelGain;

      ch.setAttribute('transform',
        `translate(${labelMargin},${baselineY}) scale(${newPxPerSec},${yScale * effectiveGain})`);
    });

    // Mark channels with non-default individual gain
    const labelsG = svg.querySelector('g.channel-labels');
    if (labelsG) {
      const labels = labelsG.querySelectorAll('text');
      labels.forEach((labelEl, drawIdx) => {
        const chGain = channelGains[drawIdx];
        const baseLabel = labelEl.textContent.replace(/ \*$/, '');
        if (chGain !== undefined && Math.abs(chGain - 1.0) > 0.01) {
          labelEl.textContent = baseLabel + ' *';
        } else {
          labelEl.textContent = baseLabel;
        }
      });
    }

    // Update grid lines
    const gridG = svg.querySelector('g.grid');
    if (gridG) {
      const topMargin = parseFloat(svg.getAttribute('viewBox').split(' ')[1]) || 0;
      const viewBoxHeight = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
      const bottomMargin = 8;
      const plotHeight = viewBoxHeight - topMargin - 5 - bottomMargin;

      while (gridG.firstChild) gridG.removeChild(gridG.firstChild);

      const gridInterval = 1.0;
      for (let t = 0; t <= newSeconds; t += gridInterval) {
        const x = labelMargin + t * newPxPerSec;
        if (x > labelMargin + plotWidth + 0.01) break;
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x.toFixed(2));
        line.setAttribute('y1', '5.00');
        line.setAttribute('x2', x.toFixed(2));
        line.setAttribute('y2', (5 + plotHeight).toFixed(2));
        line.setAttribute('stroke', '#cccccc');
        line.setAttribute('stroke-width', '0.3');
        gridG.appendChild(line);
      }
    }

    // Update time axis labels
    const timeG = svg.querySelector('g.timeaxis');
    if (timeG) {
      while (timeG.firstChild) timeG.removeChild(timeG.firstChild);

      const startTime = parseFloat(svg.dataset.startTime) || 0;
      const viewBoxParts = svg.getAttribute('viewBox').split(' ');
      const viewBoxHeight = parseFloat(viewBoxParts[3]);
      const timeLabelY = viewBoxHeight - 8 + 1.5;

      for (let t = 0; t <= newSeconds; t += 1.0) {
        const x = labelMargin + t * newPxPerSec;
        if (x > labelMargin + plotWidth + 0.01) break;
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', x.toFixed(2));
        text.setAttribute('y', timeLabelY.toFixed(2));
        text.setAttribute('class', 'time-label');
        text.textContent = `${(startTime + t).toFixed(4).replace(/\.?0+$/, '')}s`;
        timeG.appendChild(text);
      }
    }
  }
}

customElements.define('eeg-viewer', EegViewer);
